package pl.brokenranks.tool.broken_ranks_tool.progressionpath.dto;

import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
import java.util.Set;
import pl.brokenranks.tool.broken_ranks_tool.equipment.domain.enums.CHARACTER_CLASS;
import pl.brokenranks.tool.broken_ranks_tool.equipment.dto.EquipmentRequest;

/** The desired build; earlier equipment is generated by the planner. */
public record ProgressionTargetRequest(
        @NotNull CHARACTER_CLASS characterClass,
        @Min(1) @Max(140) int targetLevel,
        @NotNull @Valid EquipmentRequest targetEquipment,
        @Size(max = 3) Set<@NotNull @Pattern(regexp = "ring1|ring2|necklace") String> resSlots,
        Boolean balanceStats,
        @Min(0) @Max(140) Integer minItemLevelGap) {
    public ProgressionTargetRequest {
        balanceStats = Boolean.TRUE.equals(balanceStats);
        minItemLevelGap = minItemLevelGap == null ? 0 : minItemLevelGap;
    }

    public ProgressionTargetRequest(
            CHARACTER_CLASS characterClass,
            int targetLevel,
            EquipmentRequest targetEquipment,
            Set<String> resSlots,
            Boolean balanceStats) {
        this(characterClass, targetLevel, targetEquipment, resSlots, balanceStats, 0);
    }

    public ProgressionTargetRequest(
            CHARACTER_CLASS characterClass,
            int targetLevel,
            EquipmentRequest targetEquipment,
            Set<String> resSlots) {
        this(characterClass, targetLevel, targetEquipment, resSlots, false, 0);
    }
}
